        assert isinstance(result, float)


class TestBasicCalculations:
    def test_price_equals_center_returns_zero(self):
        assert calculate_distance_from_center(100.0, 100.0) == 0.0

    def test_price_above_center(self):
        result = calculate_distance_from_center(110.0, 100.0)
        assert math.isclose(result, 10.0, rel_tol=1e-9)

    def test_price_below_center(self):
        result = calculate_distance_from_center(90.0, 100.0)
        assert math.isclose(result, -10.0, rel_tol=1e-9)

    def test_price_double_center(self):
        result = calculate_distance_from_center(200.0, 100.0)
        assert math.isclose(result, 100.0, rel_tol=1e-9)

    def test_price_is_zero(self):
        result = calculate_distance_from_center(0.0, 100.0)
        assert math.isclose(result, -100.0, rel_tol=1e-9)

    def test_fractional_result(self):
        result = calculate_distance_from_center(101.5, 100.0)
        assert math.isclose(result, 1.5, rel_tol=1e-9)


class TestNegativeValues:
    def test_negative_center_price_above(self):
        # price=-50, center=-100 -> ((-50 - -100) / -100) * 100 = -50.0
        result = calculate_distance_from_center(-50.0, -100.0)
        assert math.isclose(result, -50.0, rel_tol=1e-9)

    def test_negative_center_price_below(self):
        # price=-150, center=-100 -> ((-150 - -100) / -100) * 100 = 50.0
        result = calculate_distance_from_center(-150.0, -100.0)
        assert math.isclose(result, 50.0, rel_tol=1e-9)

    def test_negative_price_positive_center(self):
        result = calculate_distance_from_center(-10.0, 100.0)
        assert math.isclose(result, -110.0, rel_tol=1e-9)

    def test_positive_price_negative_center(self):
        # price=10, center=-100 -> ((10 - -100)/-100)*100 = -110.0
        result = calculate_distance_from_center(10.0, -100.0)
        assert math.isclose(result, -110.0, rel_tol=1e-9)

    def test_both_negative_equal(self):
        result = calculate_distance_from_center(-100.0, -100.0)
        assert result == 0.0


class TestLargeAndSmallValues:
    def test_very_large_values(self):
        result = calculate_distance_from_center(1e12 + 1e10, 1e12)
        assert math.isclose(result, 1.0, rel_tol=1e-6)

    def test_very_small_center(self):
        result = calculate_distance_from_center(0.0002, 0.0001)
        assert math.isclose(result, 100.0, rel_tol=1e-9)

    def test_very_small_difference(self):
        result = calculate_distance_from_center(100.0001, 100.0)
        assert math.isclose(result, 0.0001, rel_tol=1e-6)

    def test_large_negative_distance(self):
        result = calculate_distance_from_center(1.0, 1000000.0)
        assert math.isclose(result, -99.9999, rel_tol=1e-6)


class TestReturnType:
    def test_returns_float_for_int_inputs(self):
        result = calculate_distance_from_center(110, 100)
        assert isinstance(result, float)
        assert math.isclose(result, 10.0, rel_tol=1e-9)

    def test_returns_float_for_float_inputs(self):
        result = calculate_distance_from_center(110.0, 100.0)
        assert isinstance(result, float)


class TestSymmetryAndProperties:
    @pytest.mark.parametrize("price,center", [
        (100.0, 50.0),
        (50.0, 100.0),
        (1.0, 3.0),
        (-20.0, 40.0),
        (0.5, 0.25),
    ])
    def test_formula_matches_manual_computation(self, price, center):
        expected = ((price - center) / center) * 100
        result = calculate_distance_from_center(price, center)
        assert math.isclose(result, expected, rel_tol=1e-9)

    def test_doubling_price_and_center_gives_same_distance(self):
        r1 = calculate_distance_from_center(150.0, 100.0)
        r2 = calculate_distance_from_center(300.0, 200.0)
        assert math.isclose(r1, r2, rel_tol=1e-9)
