        assert calculate_distance_from_center(-100.0, -100.0) == pytest.approx(0.0)

    def test_small_fractional_values(self):
        result = calculate_distance_from_center(0.011, 0.01)
        assert result == pytest.approx(10.0)

    def test_large_numbers(self):
        result = calculate_distance_from_center(1_500_000.0, 1_000_000.0)
        assert result == pytest.approx(50.0)

