    @pytest.mark.parametrize(
        "price, center, expected",
        [
            (100.0, 100.0, 0.0),
            (150.0, 100.0, 50.0),
            (50.0, 100.0, -50.0),
            (0.0, 100.0, -100.0),
            (300.0, 100.0, 200.0),
            (100.0, 200.0, -50.0),
        ],
    )
    def test_parametrized_known_values(self, price, center, expected):
        assert calculate_distance_from_center(price, center) == pytest.approx(expected)

    def test_result_is_float_type_for_normal_case(self):
        result = calculate_distance_from_center(110.0, 100.0)
