import pytest

from solution import calculate_order_total


class TestNoFee:
    """Behavior when fee_rate is zero or omitted (uses the default)."""

    def test_default_fee_rate_omitted(self):
        assert calculate_order_total(10.0, 5.0) == pytest.approx(50.0)

    def test_explicit_zero_fee_rate(self):
        assert calculate_order_total(10.0, 5.0, 0.0) == pytest.approx(50.0)

    def test_negative_amount_no_fee(self):
        assert calculate_order_total(10.0, -5.0) == pytest.approx(-50.0)

    def test_zero_price_no_fee(self):
        assert calculate_order_total(0.0, 5.0) == pytest.approx(0.0)

    def test_zero_amount_no_fee(self):
        assert calculate_order_total(10.0, 0.0) == pytest.approx(0.0)


class TestBuyOrderWithFee:
    """amount > 0: fee should be added on top of the base total."""

    def test_positive_amount_positive_price(self):
        # base_total = 100, fee = 100 * 0.1 = 10 -> total = 110
        assert calculate_order_total(10.0, 10.0, 0.1) == pytest.approx(110.0)

    def test_small_fee_rate(self):
        assert calculate_order_total(100.0, 2.0, 0.01) == pytest.approx(202.0)

    def test_full_fee_rate(self):
        # fee_rate of 1.0 doubles the base total for a buy
        assert calculate_order_total(50.0, 2.0, 1.0) == pytest.approx(200.0)

    def test_negative_price_positive_amount(self):
        # base_total = -100, fee = abs(-100) * 0.1 = 10, amount > 0 -> total = -90
        assert calculate_order_total(-10.0, 10.0, 0.1) == pytest.approx(-90.0)


class TestSellOrderWithFee:
    """amount < 0: fee should be subtracted from the base total."""

    def test_negative_amount_positive_price(self):
        # base_total = -100, fee = 100 * 0.1 = 10, amount < 0 -> total = -110
        assert calculate_order_total(10.0, -10.0, 0.1) == pytest.approx(-110.0)

    def test_small_fee_rate(self):
        assert calculate_order_total(100.0, -2.0, 0.01) == pytest.approx(-202.0)

    def test_negative_price_negative_amount(self):
        # base_total = 100 (neg * neg), fee = abs(100) * 0.1 = 10, amount < 0 -> total = 90
        assert calculate_order_total(-10.0, -10.0, 0.1) == pytest.approx(90.0)


class TestZeroAmountEdgeCase:
    """amount == 0 takes the 'else' branch (fee subtracted), but base_total is 0 too."""

    def test_zero_amount_with_fee(self):
        # base_total = 0 regardless of fee_rate; amount > 0 is False -> fee subtracted, but fee is 0
        assert calculate_order_total(10.0, 0.0, 0.5) == pytest.approx(0.0)

    def test_zero_amount_zero_price_with_fee(self):
        assert calculate_order_total(0.0, 0.0, 0.5) == pytest.approx(0.0)


class TestZeroPriceEdgeCase:
    def test_zero_price_positive_amount_with_fee(self):
        assert calculate_order_total(0.0, 5.0, 0.2) == pytest.approx(0.0)

    def test_zero_price_negative_amount_with_fee(self):
        assert calculate_order_total(0.0, -5.0, 0.2) == pytest.approx(0.0)


class TestFloatingPointAndTypes:
    def test_fractional_values(self):
        # base_total = 3.5 * 2 = 7.0, fee = 7.0 * 0.05 = 0.35 -> total = 7.35
        assert calculate_order_total(3.5, 2.0, 0.05) == pytest.approx(7.35)

    def test_int_arguments_accepted(self):
        assert calculate_order_total(10, 5, 0) == pytest.approx(50)

    def test_returns_float_like_value(self):
