import math

import pytest

from solution import calculate_order_total


class TestBasicBuyOrders:
    def test_buy_without_fee(self):
        assert calculate_order_total(10.0, 5.0) == pytest.approx(50.0)

    def test_buy_with_fee(self):
        # base_total = 100, fee = 100 * 0.01 = 1, total = 101
        result = calculate_order_total(10.0, 10.0, 0.01)
        assert result == pytest.approx(101.0)

    def test_buy_with_zero_price(self):
        result = calculate_order_total(0.0, 10.0, 0.05)
        assert result == pytest.approx(0.0)

    def test_buy_fractional_amount(self):
        # base_total = 25, fee = 25 * 0.02 = 0.5, total = 25.5
        result = calculate_order_total(50.0, 0.5, 0.02)
        assert result == pytest.approx(25.5)


class TestSellOrders:
    def test_sell_without_fee(self):
        # amount negative, no fee -> just base total
        result = calculate_order_total(10.0, -5.0)
        assert result == pytest.approx(-50.0)

    def test_sell_with_fee_positive_price(self):
        # base_total = 10 * -10 = -100, fee = abs(-100)*0.01 = 1
        # amount <= 0 so total = base_total - fee = -101
        result = calculate_order_total(10.0, -10.0, 0.01)
        assert result == pytest.approx(-101.0)

    def test_sell_with_negative_price(self):
        # price negative, amount negative -> base_total positive
        # base_total = -10 * -10 = 100, fee = 100*0.01=1
        # amount is negative -> subtract fee -> 99
        result = calculate_order_total(-10.0, -10.0, 0.01)
        assert result == pytest.approx(99.0)


class TestZeroAmount:
    def test_zero_amount_no_fee(self):
        assert calculate_order_total(10.0, 0.0) == pytest.approx(0.0)

    def test_zero_amount_with_fee_treated_as_sell_branch(self):
        # amount == 0 -> "amount > 0" is False, so branch subtracts fee
        # base_total = 0, fee = 0 -> total = 0 regardless
        result = calculate_order_total(10.0, 0.0, 0.5)
        assert result == pytest.approx(0.0)


class TestNegativePriceBuy:
    def test_negative_price_positive_amount_no_fee(self):
        # base_total = -10 * 5 = -50
        result = calculate_order_total(-10.0, 5.0)
        assert result == pytest.approx(-50.0)

    def test_negative_price_positive_amount_with_fee(self):
        # base_total = -50, fee = abs(-50)*0.1 = 5
        # amount > 0 -> total = base_total + fee = -45
        result = calculate_order_total(-10.0, 5.0, 0.1)
        assert result == pytest.approx(-45.0)


class TestFeeRateEdgeCases:
    def test_default_fee_rate_is_zero(self):
        assert calculate_order_total(3.0, 4.0) == calculate_order_total(3.0, 4.0, 0.0)

    def test_full_fee_rate_buy(self):
        # fee_rate = 1.0 -> fee equals base_total magnitude
        result = calculate_order_total(10.0, 10.0, 1.0)
        assert result == pytest.approx(200.0)

