    def test_fee_scales_with_price_and_amount(self):
        result = calculate_order_total(2.5, 4.0, 0.2)
        # base_total = 10, fee = 2, total = 12
        assert result == pytest.approx(12.0)

    def test_small_fee_rate(self):
        result = calculate_order_total(100.0, 1.0, 0.001)
        assert result == pytest.approx(100.1)


class TestFeeOnSell:
    def test_negative_amount_subtracts_fee(self):
        # base_total = -100, fee = abs(-100) * 0.1 = 10, total = -100 - 10 = -110
        result = calculate_order_total(10.0, -10.0, 0.1)
        assert result == pytest.approx(-110.0)

    def test_negative_amount_small_fee(self):
        result = calculate_order_total(50.0, -2.0, 0.05)
        # base_total = -100, fee = 5, total = -105
        assert result == pytest.approx(-105.0)


class TestNegativePrice:
    def test_negative_price_positive_amount(self):
        # base_total = -50, amount > 0 so fee is added
        # fee = abs(-50) * 0.1 = 5, total = -50 + 5 = -45
        result = calculate_order_total(-10.0, 5.0, 0.1)
        assert result == pytest.approx(-45.0)

    def test_negative_price_negative_amount(self):
        # base_total = 50 (neg * neg), amount < 0 so fee subtracted
        # fee = abs(50) * 0.1 = 5, total = 50 - 5 = 45
        result = calculate_order_total(-10.0, -5.0, 0.1)
        assert result == pytest.approx(45.0)


class TestZeroAmountEdgeCase:
    def test_zero_amount_treated_as_not_greater_than_zero(self):
        # amount = 0 -> "amount > 0" is False, so fee (0) is subtracted (still 0)
        result = calculate_order_total(50.0, 0.0, 0.5)
        assert result == 0.0


class TestFeeRateExtremes:
    def test_full_fee_rate_buy(self):
        # fee_rate = 1.0 -> fee equals base_total, total doubles
        result = calculate_order_total(10.0, 10.0, 1.0)
        assert result == pytest.approx(200.0)

    def test_full_fee_rate_sell(self):
        result = calculate_order_total(10.0, -10.0, 1.0)
        assert result == pytest.approx(-200.0)

    def test_zero_fee_rate_explicit(self):
        assert calculate_order_total(15.0, 3.0, 0.0) == 45.0

    def test_negative_fee_rate_buy_reduces_total(self):
        # unusual but mathematically valid: negative fee_rate flips fee sign
        result = calculate_order_total(10.0, 10.0, -0.1)
        # base_total = 100, fee = abs(100) * -0.1 = -10, total = 100 + (-10) = 90
        assert result == pytest.approx(90.0)


class TestFloatingPointAndTypes:
    def test_float_precision(self):
        result = calculate_order_total(0.1, 3.0, 0.01)
        base_total = 0.1 * 3.0
        expected = base_total + abs(base_total) * 0.01
        assert result == pytest.approx(expected)

    def test_integer_inputs_return_numeric(self):
        result = calculate_order_total(10, 5, 0)
        assert result == 50

    def test_large_values(self):
        result = calculate_order_total(1_000_000.0, 1_000.0, 0.001)
        base_total = 1_000_000.0 * 1_000.0
        expected = base_total + base_total * 0.001
        assert result == pytest.approx(expected)

    def test_result_not_nan(self):
        result = calculate_order_total(10.0, 10.0, 0.1)
        assert not math.isnan(result)
