import pytest

from solution import _process_websocket_test_results


def _run_capturing_stdout(result_container):
    """Helper to call the function while capturing stdout output."""
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        result = _process_websocket_test_results(result_container)
    return result, buf.getvalue()


class TestErrorPresent:
    def test_error_truthy_string_returns_false(self):
        result, output = _run_capturing_stdout(
            {"error": "connection refused", "success": False}
        )
        assert result is False
        assert "❌ WebSocket test failed: connection refused" in output

    def test_error_truthy_takes_precedence_over_success(self):
        # Even if success is True, a truthy error should win.
        result, output = _run_capturing_stdout(
            {"error": "timeout", "success": True}
        )
        assert result is False
        assert "❌ WebSocket test failed: timeout" in output

    def test_error_message_included_in_print(self):
        result, output = _run_capturing_stdout(
            {"error": "handshake failed", "success": False}
        )
        assert result is False
        assert "handshake failed" in output

    def test_error_truthy_non_string(self):
        # Non-string truthy error values should still be handled and formatted.
        result, output = _run_capturing_stdout(
            {"error": ["some", "error", "list"], "success": False}
        )
        assert result is False
        assert "❌ WebSocket test failed:" in output

    def test_error_truthy_integer(self):
        result, output = _run_capturing_stdout(
            {"error": 42, "success": False}
        )
        assert result is False
        assert "42" in output


class TestNoErrorSuccess:
    def test_no_error_success_true_returns_true(self):
        result, output = _run_capturing_stdout(
            {"error": None, "success": True}
        )
        assert result is True
        assert output == ""

    def test_no_error_success_true_empty_string_error(self):
        result, output = _run_capturing_stdout(
            {"error": "", "success": True}
        )
        assert result is True
        assert output == ""

    def test_no_error_success_true_zero_error(self):
        result, output = _run_capturing_stdout(
            {"error": 0, "success": True}
        )
        assert result is True
        assert output == ""

    def test_no_error_success_true_empty_list_error(self):
        result, output = _run_capturing_stdout(
            {"error": [], "success": True}
        )
        assert result is True
        assert output == ""


class TestUnknownError:
    def test_no_error_no_success_returns_false(self):
        result, output = _run_capturing_stdout(
            {"error": None, "success": False}
        )
        assert result is False
        assert "❌ WebSocket test failed: Unknown error" in output

    def test_empty_error_empty_success_falsy_values(self):
        result, output = _run_capturing_stdout(
            {"error": "", "success": 0}
        )
        assert result is False
        assert "❌ WebSocket test failed: Unknown error" in output

    def test_both_falsy_none(self):
        result, output = _run_capturing_stdout(
            {"error": None, "success": None}
        )
        assert result is False
        assert "❌ WebSocket test failed: Unknown error" in output

    def test_both_falsy_empty_containers(self):
        result, output = _run_capturing_stdout(
            {"error": [], "success": {}}
        )
        assert result is False
        assert "❌ WebSocket test failed: Unknown error" in output


class TestMissingKeys:
    def test_missing_error_key_raises_key_error(self):
        with pytest.raises(KeyError):
            _process_websocket_test_results({"success": True})

    def test_missing_success_key_raises_key_error_when_error_falsy(self):
        with pytest.raises(KeyError):
            _process_websocket_test_results({"error": None})

    def test_missing_success_key_not_reached_when_error_truthy(self):
        # If error is truthy, function returns before checking "success",
        # so a missing "success" key should NOT raise.
        result, output = _run_capturing_stdout({"error": "boom"})
        assert result is False
        assert "boom" in output

    def test_empty_dict_raises_key_error(self):
        with pytest.raises(KeyError):
            _process_websocket_test_results({})


class TestReturnType:
    def test_return_type_is_bool_on_error(self):
        result, _ = _run_capturing_stdout({"error": "x", "success": False})
        assert isinstance(result, bool)

    def test_return_type_is_bool_on_success(self):
        result, _ = _run_capturing_stdout({"error": None, "success": True})
        assert isinstance(result, bool)

    def test_return_type_is_bool_on_unknown_error(self):
        result, _ = _run_capturing_stdout({"error": None, "success": False})
        assert isinstance(result, bool)
