        assert result is False
        captured = capsys.readouterr()
        assert "❌ WebSocket test failed: connection refused" in captured.out

    def test_error_takes_precedence_over_success(self, capsys):
        # Even if success is truthy, a truthy error should win.
        result_container = {"error": "timeout", "success": True}

        result = _process_websocket_test_results(result_container)

        assert result is False
        captured = capsys.readouterr()
        assert "❌ WebSocket test failed: timeout" in captured.out

