"""Unit tests for count_orders_by_type from solution.py."""

from types import SimpleNamespace

import pytest

from solution import count_orders_by_type


def make_order(order_type):
    """Create a minimal object with an order_type attribute."""
    return SimpleNamespace(order_type=order_type)


class TestCountOrdersByType:
    def test_empty_list_returns_empty_dict(self):
        assert count_orders_by_type([]) == {}

    def test_single_order(self):
        orders = [make_order("standard")]
        assert count_orders_by_type(orders) == {"standard": 1}

    def test_multiple_orders_same_type(self):
        orders = [make_order("standard") for _ in range(4)]
        assert count_orders_by_type(orders) == {"standard": 4}

    def test_multiple_orders_different_types(self):
        orders = [
            make_order("standard"),
            make_order("express"),
            make_order("standard"),
            make_order("bulk"),
            make_order("express"),
            make_order("standard"),
        ]
        assert count_orders_by_type(orders) == {
            "standard": 3,
            "express": 2,
            "bulk": 1,
        }

    def test_returns_dict_type(self):
        orders = [make_order("standard")]
        result = count_orders_by_type(orders)
        assert isinstance(result, dict)

    def test_does_not_mutate_input_list(self):
        orders = [make_order("standard"), make_order("express")]
        orders_copy = list(orders)
        count_orders_by_type(orders)
        assert orders == orders_copy

    def test_result_keys_match_unique_order_types(self):
        orders = [make_order("a"), make_order("b"), make_order("a"), make_order("c")]
        result = count_orders_by_type(orders)
        assert set(result.keys()) == {"a", "b", "c"}

    def test_counts_sum_to_total_orders(self):
        orders = [make_order("a"), make_order("b"), make_order("a"), make_order("c"), make_order("a")]
        result = count_orders_by_type(orders)
        assert sum(result.values()) == len(orders)

    def test_order_type_can_be_non_string_hashable(self):
        orders = [make_order(1), make_order(2), make_order(1)]
        assert count_orders_by_type(orders) == {1: 2, 2: 1}

    def test_order_type_case_sensitivity(self):
        orders = [make_order("Standard"), make_order("standard")]
        result = count_orders_by_type(orders)
        assert result == {"Standard": 1, "standard": 1}

    def test_large_number_of_orders(self):
        orders = [make_order("standard") for _ in range(1000)] + [
            make_order("express") for _ in range(500)
        ]
        result = count_orders_by_type(orders)
        assert result == {"standard": 1000, "express": 500}

    def test_none_as_order_type(self):
        orders = [make_order(None), make_order(None), make_order("standard")]
        result = count_orders_by_type(orders)
        assert result == {None: 2, "standard": 1}

    def test_object_missing_order_type_raises_attribute_error(self):
        class Empty:
            pass

        with pytest.raises(AttributeError):
            count_orders_by_type([Empty()])

    def test_single_type_repeated_many_times_count_accuracy(self):
        orders = [make_order("gift") for _ in range(37)]
        result = count_orders_by_type(orders)
        assert result["gift"] == 37
        assert len(result) == 1
