class Order:
    """Simple stand-in object exposing an `order_type` attribute."""

    def __init__(self, order_type):
        self.order_type = order_type


def make_orders(*order_types):
    return [Order(t) for t in order_types]


class TestCountOrdersByType:
    def test_empty_list_returns_empty_dict(self):
        assert count_orders_by_type([]) == {}

    def test_single_order(self):
