        orders = make_orders("buy", "sell", "buy", "hold", "sell", "sell")
        assert count_orders_by_type(orders) == {"buy": 2, "sell": 3, "hold": 1}

    def test_all_distinct_types(self):
        orders = make_orders("buy", "sell", "hold")
        assert count_orders_by_type(orders) == {"buy": 1, "sell": 1, "hold": 1}

