import pytest
from solution import generate_levels


def test_returns_correct_number_of_levels():
    bid_levels, ask_levels = generate_levels(center_price=100.0, spread_pct=2.0, levels=5)
    assert (len(bid_levels), len(ask_levels)) == (5, 5)


def test_computes_expected_prices_for_known_input():
    bid_levels, ask_levels = generate_levels(center_price=100.0, spread_pct=2.0, levels=2)
    assert (bid_levels, ask_levels) == pytest.approx(([99.5, 99.0], [100.5, 101.0]))


def test_bid_and_ask_are_symmetric_around_center_price():
    center_price = 50.0
    bid_levels, ask_levels = generate_levels(center_price=center_price, spread_pct=4.0, levels=4)
    assert all(
        bid + ask == pytest.approx(2 * center_price)
        for bid, ask in zip(bid_levels, ask_levels)
    )

