from solution import generate_levels


def test_basic_values():
    bid_levels, ask_levels = generate_levels(100.0, 2.0, 2)
    assert bid_levels == pytest.approx([99.5, 99.0]) and ask_levels == pytest.approx([100.5, 101.0])


def test_returns_correct_number_of_levels():
    bid_levels, ask_levels = generate_levels(50.0, 1.0, 5)
    assert len(bid_levels) == 5 and len(ask_levels) == 5


def test_bid_ask_symmetric_around_center():
    center_price = 200.0
    bid_levels, ask_levels = generate_levels(center_price, 3.0, 4)
    assert all(
        bid + ask == pytest.approx(2 * center_price)
        for bid, ask in zip(bid_levels, ask_levels)
    )

