test_source_raw:
import pytest

from solution import generate_levels


def test_generates_correct_prices_for_typical_input():
    bid_levels, ask_levels = generate_levels(100.0, 2.0, 2)

    assert bid_levels == pytest.approx([99.5, 99.0]) and ask_levels == pytest.approx(
        [100.5, 101.0]
    )


def test_raises_zero_division_error_when_levels_is_zero():
    with pytest.raises(ZeroDivisionError):
        generate_levels(100.0, 2.0, 0)


def test_levels_are_symmetric_around_center_price():
    center_price = 50.0
    bid_levels, ask_levels = generate_levels(center_price, 4.0, 3)

    assert [center_price - b for b in bid_levels] == pytest.approx(
        [a - center_price for a in ask_levels]
    )

