import math

import pytest

from solution import generate_levels


def test_bid_and_ask_prices_are_symmetric_around_center():
    bid_levels, ask_levels = generate_levels(center_price=100.0, spread_pct=2.0, levels=3)

    assert all(
        math.isclose((b + a) / 2, 100.0, rel_tol=1e-9)
        for b, a in zip(bid_levels, ask_levels)
    )


def test_levels_count_determines_list_lengths():
    bid_levels, ask_levels = generate_levels(center_price=50.0, spread_pct=1.0, levels=5)

    assert len(bid_levels) == 5 and len(ask_levels) == 5


def test_zero_levels_raises_zero_division_error():
    with pytest.raises(ZeroDivisionError):
        generate_levels(center_price=100.0, spread_pct=2.0, levels=0)

