import pytest
from solution import separate_buy_sell_orders


class Order:
    def __init__(self, amount):
        self.amount = amount


def test_separates_positive_and_negative_amounts():
    orders = [Order(10), Order(-5), Order(3), Order(-2)]

    buys, sells = separate_buy_sell_orders(orders)

    assert buys == [orders[0], orders[2]] and sells == [orders[1], orders[3]]


def test_zero_amount_excluded_from_both_lists():
    orders = [Order(0)]

    buys, sells = separate_buy_sell_orders(orders)

    assert buys == [] and sells == []


def test_empty_orders_list_returns_empty_tuples():
    result = separate_buy_sell_orders([])

    assert result == ([], [])

