import pytest
from solution import separate_buy_sell_orders


class Order:
    def __init__(self, amount):
        self.amount = amount


def test_separates_positive_and_negative_amounts_into_correct_lists():
    buy, sell = Order(10), Order(-5)
    buy_orders, sell_orders = separate_buy_sell_orders([buy, sell])
    assert buy_orders == [buy] and sell_orders == [sell]


def test_zero_amount_order_is_excluded_from_both_lists():
    buy_orders, sell_orders = separate_buy_sell_orders([Order(0)])
