import pytest

from solution import calculate_distance_from_center


class TestCenterIsZero:
    def test_zero_center_returns_zero_regardless_of_price(self):
        # Documented special case: division by zero is guarded and short-circuited.
        assert calculate_distance_from_center(123.45, 0) == 0.0

    def test_zero_center_with_zero_price_returns_zero(self):
        assert calculate_distance_from_center(0, 0) == 0.0

    def test_zero_center_with_negative_price_returns_zero(self):
        assert calculate_distance_from_center(-999.0, 0) == 0.0


class TestPriceEqualsCenter:
    def test_positive_center_no_distance(self):
        assert calculate_distance_from_center(100.0, 100.0) == pytest.approx(0.0)

    def test_negative_center_no_distance(self):
        assert calculate_distance_from_center(-50.0, -50.0) == pytest.approx(0.0)


class TestDistanceSign:
    def test_price_above_positive_center_is_positive_percentage(self):
        assert calculate_distance_from_center(110.0, 100.0) == pytest.approx(10.0)

    def test_price_below_positive_center_is_negative_percentage(self):
        assert calculate_distance_from_center(90.0, 100.0) == pytest.approx(-10.0)

    def test_price_above_negative_center_is_negative_percentage(self):
        # ((-25) - (-50)) / (-50) * 100 = 25 / -50 * 100 = -50.0
        assert calculate_distance_from_center(-25.0, -50.0) == pytest.approx(-50.0)

    def test_price_below_negative_center_is_positive_percentage(self):
        # ((-75) - (-50)) / (-50) * 100 = -25 / -50 * 100 = 50.0
        assert calculate_distance_from_center(-75.0, -50.0) == pytest.approx(50.0)


class TestMagnitude:
    def test_double_price_yields_hundred_percent(self):
        assert calculate_distance_from_center(200.0, 100.0) == pytest.approx(100.0)

    def test_zero_price_with_positive_center_yields_negative_hundred_percent(self):
        assert calculate_distance_from_center(0.0, 100.0) == pytest.approx(-100.0)

    def test_small_center_amplifies_relative_distance(self):
        assert calculate_distance_from_center(2.0, 1.0) == pytest.approx(100.0)


def test_return_type_is_float():
    result = calculate_distance_from_center(110, 100)
    assert isinstance(result, float)
