import pytest
from solution import calculate_order_total


class TestNoFee:
    def test_default_fee_rate_is_zero(self):
        # fee_rate has a default of 0.0 — omitting it must leave the total untouched.
        assert calculate_order_total(100.0, 5.0) == pytest.approx(500.0)

    def test_explicit_zero_fee_rate_matches_default(self):
        assert calculate_order_total(50.0, 3.0, fee_rate=0.0) == pytest.approx(150.0)


class TestBuyOrderFeeAddition:
    def test_positive_amount_adds_fee_on_top_of_base_total(self):
        # amount > 0 => fee is added: 100*2 + (200*0.01) = 202
        assert calculate_order_total(100.0, 2.0, fee_rate=0.01) == pytest.approx(202.0)


class TestSellOrderFeeSubtraction:
    def test_negative_amount_subtracts_fee_from_base_total(self):
        # amount < 0 => fee is subtracted: 100*-2 - (200*0.01) = -202
        assert calculate_order_total(100.0, -2.0, fee_rate=0.01) == pytest.approx(-202.0)


class TestZeroAmountBoundary:
    def test_zero_amount_yields_zero_total_regardless_of_price_or_fee(self):
        # base_total is 0, and amount > 0 is False for amount == 0, so branch subtracts
        # a zero fee — result must be exactly 0 for any price/fee_rate.
        assert calculate_order_total(999.0, 0.0, fee_rate=0.5) == pytest.approx(0.0)


class TestFeeSignFollowsAmountNotBaseTotalSign:
    """Pins the non-obvious contract: the fee is added/subtracted based on the sign
    of `amount`, not the sign of `base_total` (price * amount). This means a negative
    price with a positive amount behaves like a "buy" (fee added), even though the
    resulting base_total is negative.
    """

    def test_negative_price_positive_amount_still_adds_fee(self):
        # base_total = -100 * 2 = -200, but amount > 0 so fee is ADDED, not subtracted.
        result = calculate_order_total(-100.0, 2.0, fee_rate=0.01)
        assert result == pytest.approx(-198.0)

    def test_identical_base_total_diverges_based_on_which_operand_is_negative(self):
        # Both orders produce the same base_total (-200), but the fee direction is
        # determined solely by amount's sign, producing two different totals.
        negative_price_order = calculate_order_total(-100.0, 2.0, fee_rate=0.01)
        negative_amount_order = calculate_order_total(100.0, -2.0, fee_rate=0.01)

        assert negative_price_order == pytest.approx(-198.0)
        assert negative_amount_order == pytest.approx(-202.0)
        assert negative_price_order != negative_amount_order

