"""
Unit tests for count_orders_by_type.

Orders are represented with the minimal stand-in objects the function
actually touches (an `order_type` attribute), via SimpleNamespace. This
avoids mocking the system under test while keeping tests independent of
any concrete Order class that may or may not exist in the codebase.
"""
from types import SimpleNamespace

import pytest

from solution import count_orders_by_type


def make_order(order_type):
    return SimpleNamespace(order_type=order_type)


def test_empty_list_returns_empty_dict():
    # Boundary: 0 orders.
    assert count_orders_by_type([]) == {}


def test_single_order_counts_one():
    orders = [make_order("food")]
    assert count_orders_by_type(orders) == {"food": 1}


def test_repeated_same_type_are_summed_not_overwritten():
    # Kills a mutation that sets counts[order_type] = 1 instead of
    # incrementing on repeat.
    orders = [make_order("food"), make_order("food"), make_order("food")]
    assert count_orders_by_type(orders) == {"food": 3}


def test_multiple_distinct_types_counted_independently():
    orders = [make_order("food"), make_order("drink"), make_order("food")]
    assert count_orders_by_type(orders) == {"food": 2, "drink": 1}


def test_total_of_counts_equals_number_of_orders():
    # Non-local invariant: no order is dropped or double-counted,
    # regardless of how many distinct types are present or their order.
    orders = [
        make_order("a"),
        make_order("b"),
        make_order("a"),
        make_order("c"),
        make_order("a"),
        make_order("b"),
    ]
    result = count_orders_by_type(orders)
    assert sum(result.values()) == len(orders)


@pytest.mark.parametrize("falsy_type", ["", 0])
def test_falsy_order_type_is_still_counted(falsy_type):
    # Pins that a falsy-but-valid order_type (empty string, 0) is not
    # skipped by a truthiness check; only dict.get's explicit default
    # distinguishes "absent" from "present with a falsy value".
    orders = [make_order(falsy_type), make_order(falsy_type)]
    assert count_orders_by_type(orders) == {falsy_type: 2}


def test_non_string_hashable_order_type_is_supported():
    # Documents that order_type only needs to be hashable, not a string.
    orders = [make_order(1), make_order(2), make_order(1)]
    assert count_orders_by_type(orders) == {1: 2, 2: 1}

