"""Tests for count_orders_by_type in solution.py."""
from types import SimpleNamespace
import random

import pytest

from solution import count_orders_by_type


def make_order(order_type):
    """Build a minimal stand-in for an order object with an order_type attribute."""
    return SimpleNamespace(order_type=order_type)


def test_empty_list_returns_empty_dict():
    # Boundary: zero orders should yield zero categories, not a KeyError or default bucket.
    assert count_orders_by_type([]) == {}


def test_single_order_counts_one():
    orders = [make_order("buy")]
    assert count_orders_by_type(orders) == {"buy": 1}


def test_multiple_orders_same_type_accumulate():
    orders = [make_order("buy") for _ in range(5)]
    assert count_orders_by_type(orders) == {"buy": 5}


def test_multiple_distinct_types_counted_independently():
    orders = [
        make_order("buy"),
        make_order("sell"),
        make_order("buy"),
        make_order("cancel"),
        make_order("sell"),
        make_order("buy"),
    ]
    assert count_orders_by_type(orders) == {"buy": 3, "sell": 2, "cancel": 1}


def test_order_missing_order_type_attribute_raises_attribute_error():
    # Documents current behavior: an object without order_type is not silently
    # skipped or bucketed under None -- it propagates an AttributeError.
    orders = [make_order("buy"), SimpleNamespace(other_field="x")]
    with pytest.raises(AttributeError):
        count_orders_by_type(orders)


def test_counts_are_internally_consistent_for_random_input():
    # Invariant/fuzz check: regardless of the mix of types, the counts must
    # sum to the total number of orders, and each individual count must match
    # a straightforward independent tally (via a Counter) of that type.
    rng = random.Random(1234)
    types = ["market", "limit", "stop", "stop_limit"]
    orders = [make_order(rng.choice(types)) for _ in range(200)]

    result = count_orders_by_type(orders)

    assert sum(result.values()) == len(orders)
    for order_type in types:
        expected = sum(1 for o in orders if o.order_type == order_type)
        assert result.get(order_type, 0) == expected

