import math

import pytest

from solution import safe_float_convert


class TestValidConversions:
    @pytest.mark.parametrize(
        "value, expected",
        [
            ("3.14", 3.14),
            ("-2.5", -2.5),
            ("0", 0.0),
            (42, 42.0),
            (3.14, 3.14),
            (-7, -7.0),
            ("  3.14  ", 3.14),  # float() tolerates surrounding whitespace
            ("1e3", 1000.0),  # scientific notation is valid float syntax
            (True, 1.0),  # bool is an int subclass; float(True) == 1.0
        ],
    )
    def test_convertible_values_return_float(self, value, expected):
        assert safe_float_convert(value) == expected

    def test_return_type_is_float(self):
        assert isinstance(safe_float_convert(5), float)

