    def test_special_float_strings_are_accepted(self, value):
        # Documents that float()'s special-token semantics pass through
        # unchanged rather than being caught as errors.
        result = safe_float_convert(value)
        if value == "nan":
            assert math.isnan(result)
        else:
            assert math.isinf(result)


class TestFallbackOnFailure:
